<?php require __DIR__.'/../includes/app.php';need('Customer');ensure_agreement_signature_schema();$c=me();$t=$_GET['tab']??'res';
if($_SERVER['REQUEST_METHOD']==='POST'){chk();$phone=trim($_POST['phone']??'');$address=trim($_POST['address_line']??'');$city=trim($_POST['city']??'');if($phone===''){flash('Phone number is required.','warning');header('Location: my.php?tab=profile&edit=1');exit;}q('UPDATE customers SET phone=?,address_line=?,city=? WHERE customer_id=?',[$phone,$address?:null,$city?:null,$c['customer_id']]);flash('Profile updated.');header('Location: my.php?tab=profile');exit;}
head(['res'=>'My reservations','inv'=>'My invoices','pay'=>'My payments','profile'=>'My profile'][$t]??'Account');$tabular=in_array($t,['res','inv','pay'],true);if($tabular)echo '<div class="card"><div class="card-body table-responsive">';
if($t==='res'){$r=q('SELECT r.*,v.make,v.model,a.agreement_id,a.status ast,a.renter_signed_at,a.staff_signed_at,i.invoice_number,i.status invoice_status FROM reservations r JOIN vehicles v USING(vehicle_id) LEFT JOIN rental_agreements a USING(reservation_id) LEFT JOIN invoices i ON i.invoice_id=(SELECT MAX(ii.invoice_id) FROM invoices ii WHERE ii.reservation_id=r.reservation_id) WHERE r.customer_id=? ORDER BY r.created_at DESC',[$c['customer_id']])->fetchAll();
 echo '<table class="table table-hover align-middle"><thead><tr><th scope="col">Code</th><th scope="col">Vehicle</th><th scope="col">Pickup</th><th scope="col">Return</th><th scope="col">Amount</th><th scope="col">Status</th><th scope="col">Agreement &amp; invoice</th></tr></thead><tbody>';foreach($r as $x){$action=$x['agreement_id']?badge($x['ast']).' <a class="btn btn-sm btn-outline-primary" href="'.BASE.'shared/agreement.php?id='.$x['agreement_id'].'">'.(!$x['invoice_number']?'Review &amp; create invoice':'Open agreement').'</a>'.(!empty($x['renter_signed_at'])&&!empty($x['staff_signed_at'])?' <a class="btn btn-sm btn-outline-secondary" href="'.BASE.'shared/agreement_download.php?id='.$x['agreement_id'].'"><i class="bi bi-download me-1"></i>Download PDF</a>':''):'—';if($x['invoice_number'])$action.='<small class="d-block mt-1">'.e($x['invoice_number']).' · '.e($x['invoice_status']).'</small>';echo '<tr><td>'.e($x['reservation_code']).'</td><td>'.e($x['make'].' '.$x['model']).'</td><td>'.e($x['pickup_datetime']).'</td><td>'.e($x['return_datetime']).'</td><td>'.money(max(0,$x['estimated_amount']-$x['discount_amount'])) .'</td><td>'.badge($x['status']).'</td><td>'.$action.'</td></tr>';}echo '</tbody></table>';}
elseif($t==='inv'){$r=q('SELECT b.*,r.reservation_code,a.agreement_id FROM vw_invoice_balances b LEFT JOIN reservations r USING(reservation_id) LEFT JOIN rental_agreements a USING(reservation_id) WHERE b.customer_id=? ORDER BY b.invoice_id DESC',[$c['customer_id']])->fetchAll();
 echo '<table class="table table-hover align-middle"><thead><tr><th scope="col">Invoice</th><th scope="col">Application</th><th scope="col">Date</th><th scope="col">Total</th><th scope="col">Paid</th><th scope="col">Balance</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody>';foreach($r as $x){$action='';if($x['agreement_id']&&$x['status']==='draft')$action='<a class="btn btn-sm btn-outline-primary" href="'.BASE.'shared/agreement.php?id='.$x['agreement_id'].'">Review &amp; create invoice</a>';elseif($x['agreement_id']&&$x['outstanding_balance']>0&&in_array($x['status'],['issued','partially_paid','overdue'],true))$action='<a class="btn btn-sm btn-accent" href="'.BASE.'shared/agreement.php?id='.$x['agreement_id'].'&amp;step=3">Pay invoice</a>';echo '<tr><td>'.e($x['invoice_number']).'</td><td>'.e($x['reservation_code']??'—').'</td><td>'.e($x['issue_date']).'</td><td>'.money($x['total_amount']).'</td><td>'.money($x['total_paid_gross']-$x['total_refunded']).'</td><td>'.money($x['outstanding_balance']).'</td><td>'.badge($x['status']).'</td><td>'.$action.'</td></tr>';}if(!$r)echo '<tr><td colspan="8" class="text-center text-muted py-4">No invoices yet. Review a submitted rental agreement to create your invoice.</td></tr>';echo '</tbody></table>';}
elseif($t==='pay'){$r=q('SELECT p.*,i.invoice_number FROM payments p JOIN invoices i USING(invoice_id) WHERE i.customer_id=? ORDER BY p.payment_date DESC',[$c['customer_id']])->fetchAll();
 echo '<table class="table table-hover"><thead><tr><th scope="col">Payment</th><th scope="col">Invoice</th><th scope="col">Date</th><th scope="col">Method</th><th scope="col">Reference</th><th scope="col">Amount</th><th scope="col">Status</th><th scope="col"></th></tr></thead><tbody>';foreach($r as $x)echo '<tr><td>'.e($x['payment_number']).'</td><td>'.e($x['invoice_number']).'</td><td>'.e($x['payment_date']).'</td><td>'.e($x['payment_method']).'</td><td>'.e($x['transaction_reference']).'</td><td>'.money($x['amount']).'</td><td>'.badge($x['status']).'</td><td>'.(in_array($x['status'],['completed','partially_refunded','refunded'])?'<a class="btn btn-sm btn-outline-secondary" target="_blank" href="'.BASE.'shared/receipt.php?id='.$x['payment_id'].'">Receipt</a>':'').'</td></tr>';echo '</tbody></table>';}
elseif($t==='profile'){if(isset($_GET['edit'])){?>
<div class="card profile-card"><div class="card-header d-flex justify-content-between align-items-center"><span>Update contact details</span><a class="btn btn-sm btn-outline-secondary" href="<?=BASE?>customer/my.php?tab=profile"><i class="bi bi-arrow-left me-1"></i>Back to profile</a></div><div class="card-body"><form method="post" class="row g-4"><?=csrf_f()?>
<div class="col-md-6"><label class="form-label" for="profile-phone">Phone</label><input id="profile-phone" name="phone" type="tel" autocomplete="tel" class="form-control" value="<?=e($c['phone'])?>" required></div>
<div class="col-md-6"><label class="form-label" for="profile-address">Address</label><input id="profile-address" name="address_line" autocomplete="street-address" class="form-control" value="<?=e($c['address_line'])?>"></div>
<div class="col-md-6"><label class="form-label" for="profile-city">City</label><input id="profile-city" name="city" autocomplete="address-level2" class="form-control" value="<?=e($c['city'])?>"></div>
<div class="col-12 d-flex flex-wrap gap-2"><button class="btn btn-primary"><i class="bi bi-check2-circle me-1"></i>Save changes</button><a class="btn btn-outline-secondary" href="<?=BASE?>customer/my.php?tab=profile">Cancel</a></div></form></div></div>
<?php }else{$fullName=trim($c['first_name'].' '.$c['last_name']);?>
<div class="profile-card card"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-3"><div><div class="text-muted small text-uppercase fw-semibold">Account overview</div><h2 class="h5 mb-0 mt-1">Your profile</h2></div><a class="btn btn-primary" href="<?=BASE?>customer/my.php?tab=profile&amp;edit=1"><i class="bi bi-pencil-square me-2"></i>Update profile</a></div><div class="card-body">
<div class="profile-summary"><div class="profile-summary-avatar" aria-hidden="true"><?=e(user_initials($fullName))?></div><div><h3 class="h5 mb-1"><?=e($fullName)?></h3><div class="text-muted"><?=e($c['email']?:'Not provided')?></div><div class="mt-2"><?=badge($c['status'])?> <span class="text-muted small ms-1">Customer code: <?=e($c['customer_code'])?></span></div></div></div>
<div class="profile-details mt-4"><div class="profile-detail"><span>Phone</span><strong><?=e($c['phone']?:'Not provided')?></strong></div><div class="profile-detail"><span>Address</span><strong><?=e($c['address_line']?:'Not provided')?></strong></div><div class="profile-detail"><span>City</span><strong><?=e($c['city']?:'Not provided')?></strong></div><div class="profile-detail"><span>Identification</span><strong><?=e($c['identification_type']?ucfirst(str_replace('_',' ',$c['identification_type'])).($c['identification_number']?' · '.$c['identification_number']:''):'Not provided')?></strong></div><div class="profile-detail"><span>Driving licence</span><strong><?=e($c['driving_license_number']?:'Not provided')?></strong></div><div class="profile-detail"><span>Licence expiry</span><strong><?=e($c['license_expiry_date']?:'Not provided')?></strong></div><div class="profile-detail"><span>Date of birth</span><strong><?=e($c['date_of_birth']?:'Not provided')?></strong></div></div>
</div></div><?php }}else{echo '<div class="alert alert-info" role="status">Choose a section from the navigation to view your account information.</div>'; }
if($tabular)echo '</div></div>';foot();
